        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(tokenizer.nextToken());
        String s = reader.readLine();
        int[][] positions = new int[3][n];
        int[] counts = new int[3];
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == 'V') {
                positions[0][counts[0]++] = i;
            } else if (ch == 'K') {
                positions[1][counts[1]++] = i;
            } else {
                positions[2][counts[2]++] = i;
            }
        }
        int[][][][] dp = new int[counts[0] + 1][counts[1] + 1][counts[2] + 1][2];
        for (int[][][] arr3d : dp) {
            for (int[][] arr2d : arr3d) {
                for (int[] arr1d : arr2d) {
                    Arrays.fill(arr1d, Integer.MAX_VALUE);
                }
            }
        }
        int[][][] p = new int[3][3][n];
        for (int x = 0; x < 3; x++) {
            for (int y = 0; y < 3; y++) if (x != y) {
                for (int i = 0; i < counts[x]; i++) {
                    for (int j = 0; j < counts[y]; j++) {
                        if (positions[y][j] < positions[x][i]) p[x][y][i]++;
                    }
                }
            }
        }
        dp[0][0][0][1] = 0;
        for (int i = 0; i <= counts[0]; i++) {
            for (int j = 0; j <= counts[1]; j++) {
