                            if (i < counts[0]) {
                                dp[i + 1][j][k][0] = Math.min(dp[i + 1][j][k][0], dp[i][j][k][q] + Math.max(p[0][1][i] - j, 0) + Math.max(p[0][2][i] - k, 0));
                            }
                            if (j < counts[1] && q == 1) {
                                dp[i][j + 1][k][1] = Math.min(dp[i][j + 1][k][1], dp[i][j][k][q] + Math.max(p[1][0][j] - i, 0) + Math.max(p[1][2][j] - k, 0));
                            }
                            if (k < counts[2]) {
                                dp[i][j][k + 1][1] = Math.min(dp[i][j][k + 1][1], dp[i][j][k][q] + Math.max(p[2][0][k] - i, 0) + Math.max(p[2][1][k] - j, 0));
                            }
                        }
                    }
