import sys

def solve():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    s = input[1]
    positions = [[0]*n for _ in range(3)]
    counts = [0, 0, 0]
    for i, ch in enumerate(s):
        if ch == 'V':
            positions[0][counts[0]] = i
            counts[0] += 1
        elif ch == 'K':
            positions[1][counts[1]] = i
            counts[1] += 1
        else:
            positions[2][counts[2]] = i
            counts[2] += 1

    import math
    dp = [[[[math.inf for _ in range(2)] for _ in range(counts[2]+1)] for _ in range(counts[1]+1)] for _ in range(counts[0]+1)]
    p = [[[0]*n for _ in range(3)] for _ in range(3)]
    for x in range(3):
        for y in range(3):
            if x != y:
                for i in range(counts[x]):
                    for j in range(counts[y]):
                        if positions[y][j] < positions[x][i]:
                            p[x][y][i] += 1
    dp[0][0][0][1] = 0
    for i in range(counts[0]+1):
        for j in range(counts[1]+1):
            for k in range(counts[2]+1):
                for q in range(2):
                    if dp[i][j][k][q] != math.inf:
                        if i < counts[0]:
                            val = dp[i][j][k][q] + max(p[0][1][i] - j, 0) + max(p[0][2][i] - k, 0)
                            if val < dp[i+1][j][k][0]:
                                dp[i+1][j][k][0] = val
                        if j < counts[1] and q == 1:
                            val = dp[i][j][k][q] + max(p[1][0][j] - i, 0) + max(p[1][2][j] - k, 0)
                            if val < dp[i][j+1][k][1]:
                                dp[i][j+1][k][1] = val
                        if k < counts[2]:
                            val = dp[i][j][k][q] + max(p[2][0][k] - i, 0) + max(p[2][1][k] - j, 0)
                            if val < dp[i][j][k+1][1]:
                                dp[i][j][k+1][1] = val
    print(int(min(dp[counts[0]][counts[1]][counts[2]][0], dp[counts[0]][counts[1]][counts[2]][1])))

